def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty) - sorted by price desc, then arrival asc
    sell_book = []  # List of (price, arrival_time, id, qty) - sorted by price asc, then arrival asc
    order_map = {}  # Map id -> (side, price, arrival_time) for cancellation
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arr_time = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest arrival)
                while qty > 0 and sell_book:
                    price, arr_time, sell_id, sell_qty = sell_book[0]
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, price, trade_qty])
                    qty -= trade_qty
                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (price, arr_time, sell_id, sell_qty - trade_qty)
            else:
                # Match against buy_book (highest price first, then earliest arrival)
                while qty > 0 and buy_book:
                    price, arr_time, buy_id, buy_qty = buy_book[0]
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, price, trade_qty])
                    qty -= trade_qty
                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (price, arr_time, buy_id, buy_qty - trade_qty)

        elif order[0] == 'ioc':
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest arrival)
                while qty > 0 and sell_book and sell_book[0][0] <= price:
                    sp, arr_time, sell_id, sell_qty = sell_book[0]
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sp, trade_qty])
                    qty -= trade_qty
                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (sp, arr_time, sell_id, sell_qty - trade_qty)
            else:
                # Match against buy_book (highest price first, then earliest arrival)
                while qty > 0 and buy_book and buy_book[0][0] >= price:
                    bp, arr_time, buy_id, buy_qty = buy_book[0]
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, bp, trade_qty])
                    qty -= trade_qty
                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (bp, arr_time, buy_id, buy_qty - trade_qty)

        elif order[0] == 'limit':
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest arrival)
                while qty > 0 and sell_book and sell_book[0][0] <= price:
                    sp, arr_time, sell_id, sell_qty = sell_book[0]
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sp, trade_qty])
                    qty -= trade_qty
                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (sp, arr_time, sell_id, sell_qty - trade_qty)

                # Rest remaining qty
                if qty > 0:
                    buy_book.insert(0, (price, arrival_time, order_id, qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = ('buy', price, arrival_time)
            else:
                # Match against buy_book (highest price first, then earliest arrival)
                while qty > 0 and buy_book and buy_book[0][0] >= price:
                    bp, arr_time, buy_id, buy_qty = buy_book[0]
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, bp, trade_qty])
                    qty -= trade_qty
                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (bp, arr_time, buy_id, buy_qty - trade_qty)

                # Rest remaining qty
                if qty > 0:
                    sell_book.insert(0, (price, arrival_time, order_id, qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = ('sell', price, arrival_time)

    return trades

